    "sourceFetchedAt": "2026-07-23T23:55:54.354Z",
    "sourceHash": "36732f0fcc3e21adf26283f994ded31d18f56193785529056f474da08e022e97",
    "contentHash": "b0dc5d94ed60afaecc507b8c1268a25bbaf3620ba169426b98792e80dca11cc4",
    "verificationStatus": "snapshot-hash-verified",
