    "sourceRevisionId": "20260401_508M60000100003",
    "sourceFetchedAt": "2026-07-23T23:55:55.176Z",
    "sourceHash": "7465f8ee1a97952a8bee693d7b01974491b166bdab46354cf82fe4f6354baee4",
    "contentHash": "4b8d6edbb1222be99a91a2f3f68bfc69862d3de044139cb54f3d2dbd3aa8623f",
    "verificationStatus": "snapshot-hash-verified",
